let file = """{"version":3,"file":"missingModelMetadata-vslWdBc_.js","names":[],"sources":["../../src/stores/electronDownloadStore.ts","../../src/platform/missingModel/missingModelDownload.ts","../../src/platform/missingModel/missingModelMetadata.ts"],"sourcesContent":["import { DownloadStatus } from '@comfyorg/comfyui-electron-types'\nimport type { DownloadState } from '@comfyorg/comfyui-electron-types'\nimport { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { isDesktop } from '@/platform/distribution/types'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { electronAPI } from '@/utils/envUtil'\n\nexport interface ElectronDownload extends Pick<\n  DownloadState,\n  'url' | 'filename'\n> {\n  progress?: number\n  receivedBytes?: number\n  savePath?: string\n  status?: DownloadStatus\n  totalBytes?: number\n}\n\nfunction normalizeElectronDownloadState({\n  url,\n  filename,\n  state,\n  receivedBytes,\n  totalBytes\n}: DownloadState): ElectronDownload {\n  const download: ElectronDownload = {\n    url,\n    filename,\n    status: state,\n    receivedBytes,\n    totalBytes\n  }\n\n  return Number.isFinite(receivedBytes) &&\n    receivedBytes >= 0 &&\n    Number.isFinite(totalBytes) &&\n    totalBytes > 0 &&\n    receivedBytes <= totalBytes\n    ? { ...download, progress: receivedBytes / totalBytes }\n    : download\n}\n\n/** Electron downloads store handler */\nexport const useElectronDownloadStore = defineStore('downloads', () => {\n  const downloads = ref<ElectronDownload[]>([])\n  const DownloadManager = isDesktop ? electronAPI().DownloadManager : undefined\n  const progressListeners = new Set<(download: ElectronDownload) => void>()\n  let isProgressListenerInstalled = false\n\n  const findByUrl = (url: string) =>\n    downloads.value.find((download) => url === download.url)\n\n  function notifyProgressListeners(download: ElectronDownload) {\n    for (const listener of progressListeners) {\n      // Isolated so one throwing subscriber cannot stop the others, or\n      // abandon a replay partway through.\n      try {\n        listener(download)\n      } catch (error) {\n        reportError(error, {\n          surface: 'platform',\n          errorType: 'error_notifying_download_progress_listener'\n        })\n      }\n    }\n  }\n\n  function applyProgress(data: ElectronDownload) {\n    if (!findByUrl(data.url)) {\n      downloads.value.push(data)\n    }\n\n    const download = findByUrl(data.url)\n\n    if (download) {\n      download.progress = data.progress\n      download.receivedBytes = undefined\n      download.totalBytes = undefined\n      download.status = data.status\n      download.filename = data.filename\n      download.savePath = data.savePath\n      notifyProgressListeners(download)\n    }\n  }\n\n  /** `defer` may hold an event back; returning true means it took ownership. */\n  function installProgressListener(\n    defer?: (download: ElectronDownload) => boolean\n  ) {\n    if (!DownloadManager || isProgressListenerInstalled) return\n\n    isProgressListenerInstalled = true\n    DownloadManager.onDownloadProgress((data) => {\n      if (defer?.(data)) return\n      applyProgress(data)\n    })\n  }\n\n  async function initialize() {\n    if (!isDesktop || !DownloadManager) return\n\n    // Listen immediately so no live event is missed, but hold them back until\n    // the snapshot has been applied: the snapshot describes an older moment,\n    // so replaying afterwards is what keeps a download from moving backwards.\n    const live = new Map<string, ElectronDownload>()\n    let restored = false\n    installProgressListener((download) => {\n      if (restored) return false\n      live.set(download.url, download)\n      return true\n    })\n\n    try {\n      const allDownloads = await DownloadManager.getAllDownloads()\n\n      for (const download of allDownloads) {\n        const normalizedDownload = normalizeElectronDownloadState(download)\n        const existing = findByUrl(normalizedDownload.url)\n        if (existing) {\n          Object.assign(existing, normalizedDownload)\n        } else {\n          downloads.value.push(normalizedDownload)\n        }\n      }\n    } catch {\n      // A missing snapshot must not keep live progress from being observed.\n    }\n\n    restored = true\n    for (const download of live.values()) applyProgress(download)\n    live.clear()\n  }\n\n  function subscribeToDownloadProgress(\n    listener: (download: ElectronDownload) => void\n  ) {\n    progressListeners.add(listener)\n\n    return () => progressListeners.delete(listener)\n  }\n\n  void initialize()\n\n  const start = ({\n    url,\n    savePath,\n    filename\n  }: {\n    url: string\n    savePath: string\n    filename: string\n  }) => DownloadManager!.startDownload(url, savePath, filename)\n  const pause = (url: string) => DownloadManager!.pauseDownload(url)\n  const resume = (url: string) => DownloadManager!.resumeDownload(url)\n  const cancel = (url: string) => DownloadManager!.cancelDownload(url)\n\n  return {\n    downloads,\n    start,\n    pause,\n    resume,\n    cancel,\n    findByUrl,\n    initialize,\n    subscribeToDownloadProgress,\n    inProgressDownloads: computed(() =>\n      downloads.value.filter(\n        ({ status }) => status !== DownloadStatus.COMPLETED\n      )\n    )\n  }\n})\n","import { downloadUrlToHfRepoUrl, isCivitaiModelUrl } from '@/utils/formatUtil'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { isDesktop } from '@/platform/distribution/types'\nimport { useElectronDownloadStore } from '@/stores/electronDownloadStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nconst ALLOWED_SOURCES = [\n  'https://civitai.com/',\n  'https://civitai.red/',\n  'https://huggingface.co/'\n] as const\n\n// Intentionally restrictive subset of model extensions permitted for download.\n// Does not include .bin, .onnx, .gguf — see MODEL_FILE_EXTENSIONS in\n// missingModelScan.ts for the broader scanning set.\nconst ALLOWED_SUFFIXES = [\n  '.safetensors',\n  '.sft',\n  '.ckpt',\n  '.pth',\n  '.pt'\n] as const\n\nconst WHITE_LISTED_URLS: ReadonlySet<string> = new Set([\n  'https://huggingface.co/stabilityai/stable-zero123/resolve/main/stable_zero123.ckpt',\n  'https://huggingface.co/TencentARC/T2I-Adapter/resolve/main/models/t2iadapter_depth_sd14v1.pth?download=true',\n  'https://github.com/xinntao/Real-ESRGAN/releases/download/v0.1.0/RealESRGAN_x4plus.pth',\n  'http://localhost:8188/api/devtools/fake_model.safetensors'\n])\n\nfunction isModelUrlAllowlisted(url: string): boolean {\n  return (\n    WHITE_LISTED_URLS.has(url) ||\n    ALLOWED_SOURCES.some((source) => url.startsWith(source))\n  )\n}\n\nconst MODEL_LIBRARY_TAB_ID = 'model-library'\n\nexport interface ModelWithUrl {\n  name: string\n  url: string\n  directory: string\n}\n\nexport type ModelDownloadDispatchOutcome =\n  | {\n      status: 'not-dispatched'\n      reason: 'not-downloadable' | 'missing-directory-path'\n    }\n  | { status: 'browser-requested' }\n  | {\n      status: 'host-requested'\n      host: 'desktop2' | 'electron'\n      hostResult: Promise<boolean>\n    }\n  | {\n      status: 'dispatch-failed'\n      host: 'desktop2' | 'electron'\n      error: unknown\n    }\n\nfunction openUrlInNewTab(url: string, downloadAs?: string): void {\n  try {\n    const protocol = new URL(url).protocol\n    if (protocol !== 'https:' && protocol !== 'http:') {\n      console.warn('[missingModelDownload] Blocked unsupported URL scheme')\n      return\n    }\n  } catch {\n    console.warn('[missingModelDownload] Blocked malformed download URL')\n    return\n  }\n\n  const link = document.createElement('a')\n  link.href = url\n  if (downloadAs) link.download = downloadAs\n  link.target = '_blank'\n  link.rel = 'noopener noreferrer'\n  link.click()\n}\n\nexport function openGatedRepoPage(url: string): void {\n  if (!isTrustedHuggingFaceUrl(url)) return\n  openUrlInNewTab(url)\n}\n\nfunction hasHuggingFaceHost(url: string): boolean {\n  try {\n    return new URL(url).hostname.toLowerCase() === 'huggingface.co'\n  } catch {\n    return false\n  }\n}\n\nexport function isTrustedHuggingFaceUrl(url: string): boolean {\n  try {\n    return new URL(url).origin === 'https://huggingface.co'\n  } catch {\n    return false\n  }\n}\n\n/**\n * Converts a model download URL to a browsable page URL.\n * - HuggingFace: `/resolve/` → `/blob/` (file page with model info)\n * - Civitai: strips `/api/download` or `/api/v1` prefix (model page)\n */\nexport function toBrowsableUrl(url: string): string {\n  if (isCivitaiModelUrl(url)) {\n    return url.replace('/api/download/', '/').replace('/api/v1/', '/')\n  }\n  if (hasHuggingFaceHost(url)) {\n    return url.replace('/resolve/', '/blob/')\n  }\n  return url\n}\n\nexport function isModelDownloadable(model: ModelWithUrl): boolean {\n  if (!isModelUrlAllowlisted(model.url)) return false\n  if (WHITE_LISTED_URLS.has(model.url)) return true\n  if (!ALLOWED_SUFFIXES.some((suffix) => model.name.endsWith(suffix)))\n    return false\n  return true\n}\n\ntype Desktop2Download = NonNullable<\n  NonNullable<typeof window.__comfyDesktop2>['downloadModel']\n>\n\nfunction modelDownloadRoute():\n  | { host: 'desktop2'; download: Desktop2Download }\n  | { host: 'electron' }\n  | { host: 'browser' } {\n  const bridge = window.__comfyDesktop2\n  const isRemote = bridge?.isRemote?.() ?? window.__comfyDesktop2Remote ?? false\n  if (bridge?.downloadModel && !isRemote) {\n    return { host: 'desktop2', download: bridge.downloadModel.bind(bridge) }\n  }\n  return { host: isDesktop ? 'electron' : 'browser' }\n}\n\n/**\n * Only the Electron path needs a resolved `savePath`: the desktop2 bridge takes\n * the logical directory name and decides where to write, and a browser opens\n * the URL instead.\n */\nexport function modelDownloadNeedsFolderPaths(): boolean {\n  return modelDownloadRoute().host === 'electron'\n}\n\nexport function dispatchModelDownload(\n  model: ModelWithUrl,\n  paths: Record<string, string[]>,\n  { revealLegacyDownload = true }: { revealLegacyDownload?: boolean } = {}\n): ModelDownloadDispatchOutcome {\n  if (!isModelDownloadable(model)) {\n    return { status: 'not-dispatched', reason: 'not-downloadable' }\n  }\n\n  const route = modelDownloadRoute()\n  if (route.host === 'desktop2') {\n    try {\n      return {\n        status: 'host-requested',\n        host: 'desktop2',\n        hostResult: Promise.resolve(\n          route.download(model.url, model.name, model.directory)\n        )\n      }\n    } catch (error) {\n      return { status: 'dispatch-failed', host: 'desktop2', error }\n    }\n  }\n\n  if (route.host === 'browser') {\n    openUrlInNewTab(model.url, model.name)\n    return { status: 'browser-requested' }\n  }\n\n  const savePath = paths[model.directory]?.[0]\n  if (!savePath) {\n    return { status: 'not-dispatched', reason: 'missing-directory-path' }\n  }\n\n  if (revealLegacyDownload) {\n    useSidebarTabStore().activeSidebarTabId = MODEL_LIBRARY_TAB_ID\n  }\n  try {\n    return {\n      status: 'host-requested',\n      host: 'electron',\n      hostResult: Promise.resolve(\n        useElectronDownloadStore().start({\n          url: model.url,\n          savePath,\n          filename: model.name\n        })\n      )\n    }\n  } catch (error) {\n    return { status: 'dispatch-failed', host: 'electron', error }\n  }\n}\n\nexport function downloadModel(\n  model: ModelWithUrl,\n  paths: Record<string, string[]>\n): void {\n  const outcome = dispatchModelDownload(model, paths)\n\n  if (outcome.status === 'dispatch-failed') {\n    reportError(outcome.error, {\n      surface: 'platform',\n      errorType: 'error_starting_model_download',\n      tags: { host: outcome.host }\n    })\n    return\n  }\n\n  if (outcome.status !== 'host-requested') return\n\n  void outcome.hostResult.catch((error: unknown) => {\n    reportError(error, {\n      surface: 'platform',\n      errorType: 'error_starting_model_download',\n      tags: { host: outcome.host }\n    })\n  })\n}\n\nexport interface ModelMetadata {\n  fileSize: number | null\n  gatedRepoUrl: string | null\n}\n\nexport type ModelMetadataFetchOutcome = {\n  metadata: ModelMetadata\n  resolution: 'resolved' | 'failed'\n}\n\ninterface MetadataFetchResult extends ModelMetadataFetchOutcome {\n  cacheable: boolean\n}\n\ninterface CivitaiModelFile {\n  sizeKB: number\n  downloadUrl: string\n}\n\ninterface CivitaiModelVersionResponse {\n  files: CivitaiModelFile[]\n}\n\nconst metadataCache = new Map<string, ModelMetadataFetchOutcome>()\nconst inflight = new Map<string, Promise<ModelMetadataFetchOutcome>>()\n\nexport function clearMetadataCache(): void {\n  metadataCache.clear()\n  inflight.clear()\n}\n\nasync function fetchCivitaiMetadata(\n  url: string,\n  signal?: AbortSignal\n): Promise<MetadataFetchResult> {\n  try {\n    const pathname = new URL(url).pathname\n    const versionIdMatch =\n      pathname.match(/^\\/api\\/download\\/models\\/(\\d+)$/) ??\n      pathname.match(/^\\/api\\/v1\\/models-versions\\/(\\d+)$/)\n\n    if (!versionIdMatch) {\n      return {\n        metadata: { fileSize: null, gatedRepoUrl: null },\n        resolution: 'failed',\n        cacheable: false\n      }\n    }\n\n    const [, modelVersionId] = versionIdMatch\n    const apiUrl = `https://civitai.com/api/v1/model-versions/${modelVersionId}`\n    const res = signal ? await fetch(apiUrl, { signal }) : await fetch(apiUrl)\n    if (!res.ok) {\n      return {\n        metadata: { fileSize: null, gatedRepoUrl: null },\n        resolution: 'failed',\n        cacheable: false\n      }\n    }\n\n    const data: CivitaiModelVersionResponse = await res.json()\n    const matchingFile = data.files.find((file) => {\n      const downloadUrl = file.downloadUrl\n      return (\n        typeof downloadUrl === 'string' &&\n        downloadUrl.length > 0 &&\n        downloadUrl.startsWith(url)\n      )\n    })\n    const fileSize = matchingFile?.sizeKB ? matchingFile.sizeKB * 1024 : null\n    return {\n      metadata: { fileSize, gatedRepoUrl: null },\n      resolution: 'resolved',\n      cacheable: true\n    }\n  } catch {\n    return {\n      metadata: { fileSize: null, gatedRepoUrl: null },\n      resolution: 'failed',\n      cacheable: false\n    }\n  }\n}\n\nconst GATED_STATUS_CODES = new Set([401, 403, 451])\nconst HUGGING_FACE_GATED_ERROR_CODE = 'GatedRepo'\n\nfunction failedMetadataResult(): MetadataFetchResult {\n  return {\n    metadata: { fileSize: null, gatedRepoUrl: null },\n    resolution: 'failed',\n    cacheable: false\n  }\n}\n\nfunction getGatedRepoUrl(url: string, response: Response): string | null {\n  if (!isTrustedHuggingFaceUrl(url)) return null\n  if (!GATED_STATUS_CODES.has(response.status)) return null\n  if (response.headers.get('x-error-code') !== HUGGING_FACE_GATED_ERROR_CODE) {\n    return null\n  }\n  return downloadUrlToHfRepoUrl(url)\n}\n\nfunction getResolvedHeadMetadata(response: Response): MetadataFetchResult {\n  const contentLength = response.headers.get('content-length')\n  const parsedSize = contentLength ? parseInt(contentLength, 10) : null\n  const fileSize =\n    parsedSize !== null && !Number.isNaN(parsedSize) ? parsedSize : null\n  return {\n    metadata: { fileSize, gatedRepoUrl: null },\n    resolution: 'resolved',\n    cacheable: true\n  }\n}\n\nfunction getFailedHeadMetadata(\n  url: string,\n  response: Response\n): MetadataFetchResult {\n  const gatedRepoUrl = getGatedRepoUrl(url, response)\n  if (!gatedRepoUrl) return failedMetadataResult()\n  return {\n    metadata: { fileSize: null, gatedRepoUrl },\n    resolution: 'resolved',\n    cacheable: true\n  }\n}\n\nasync function fetchHeadMetadata(\n  url: string,\n  signal?: AbortSignal\n): Promise<MetadataFetchResult> {\n  try {\n    // Deliberately uncredentialed HEADs prevent re-checks from clearing gating.\n    const response = await fetch(url, {\n      method: 'HEAD',\n      ...(s